from keras_nlp.backend import keras
from keras_nlp.layers.preprocessing.preprocessing_layer import (
    PreprocessingLayer,
)
from keras_nlp.utils.preset_utils import PREPROCESSOR_CONFIG_FILE
from keras_nlp.utils.preset_utils import TOKENIZER_CONFIG_FILE
from keras_nlp.utils.preset_utils import check_file_exists
from keras_nlp.utils.preset_utils import check_preset_class
from keras_nlp.utils.preset_utils import load_from_preset
from keras_nlp.utils.python_utils import classproperty
from keras_nlp.utils.python_utils import format_docstring


@keras.saving.register_keras_serializable(package="keras_nlp")
class Preprocessor(PreprocessingLayer):
    """Base class for model preprocessors."""

    def __init__(self, *args, **kwargs):
        self.config_file = kwargs.pop("config_file", PREPROCESSOR_CONFIG_FILE)
        super().__init__(*args, **kwargs)
        self._tokenizer = None

    def __setattr__(self, name, value):
        # Work around torch setattr for properties.
        if name in ["tokenizer"]:
            return object.__setattr__(self, name, value)
        return super().__setattr__(name, value)

    @property
    def tokenizer(self):
        """The tokenizer used to tokenize strings."""
        return self._tokenizer

    @tokenizer.setter
    def tokenizer(self, value):
        self._tokenizer = value

    def get_config(self):
        config = super().get_config()
        config["tokenizer"] = keras.layers.serialize(self.tokenizer)
        config["config_file"] = self.config_file
        return config

    @classmethod
    def from_config(cls, config):
        if "tokenizer" in config and isinstance(config["tokenizer"], dict):
            config["tokenizer"] = keras.layers.deserialize(config["tokenizer"])
        return cls(**config)

    @classproperty
    def tokenizer_cls(cls):
        return None

    @classproperty
    def presets(cls):
        return {}

    @classmethod
    def _add_missing_kwargs(cls, loader, kwargs):
        """Fill in required kwargs when loading a preprocessor from a preset.

        This is a private method used when loading a preprocessor that was not
        directly saved in the preset. This method will fill in all required
        kwargs needed to call the class constructor. For most preprocessors,
        the only required arg is `tokenizer`, but this can be overridden, e.g.
        for a preprocessor with multiple tokenizers.
        """
        if "tokenizer" not in kwargs and cls.tokenizer_cls:
            kwargs["tokenizer"] = loader.load_tokenizer(cls.tokenizer_cls)
        return kwargs

    def load_preset_assets(self, preset):
        """Load all static assets needed by the preprocessing layer.

        Args:
            preset: A local preset directory or other preset identifier.
        """
        for layer in self._flatten_layers(include_self=False):
            if hasattr(layer, "load_preset_assets"):
                layer.load_preset_assets(preset)

    def save_to_preset(self, preset_dir):
        """Save preprocessor to a preset directory.

        Args:
            preset_dir: The path to the local model preset directory.
        """
        from keras_nlp.utils.preset_utils import save_to_preset

        save_to_preset(self, preset_dir)

    @classmethod
    def from_preset(
        cls,
        preset,
        config_file=None,
        **kwargs,
    ):
        """Instantiate {{preprocessor_name}} from preset architecture.

        Args:
            preset: string. Must be one of "{{preset_names}}".
            config_file: string. The name of the config file to load the
                preprocessor from. If `None`, the preprocessor will be loaded
                either from the serialized `preprocessor.json` config if it
                exists in the preset, or reconstructed from its tokenizer.

        Examples:
        ```python
        # Load a preprocessor layer from a preset.
        preprocessor = keras_nlp.models.{{preprocessor_name}}.from_preset(
            "{{example_preset_name}}",
        )
        ```
        """
        # We support short IDs for official presets, e.g. `"bert_base_en"`.
        # Map these to a Kaggle Models handle.
        if preset in cls.presets:
            preset = cls.presets[preset]["kaggle_handle"]

        if config_file is None:
            config_file = PREPROCESSOR_CONFIG_FILE

        # If a serialized config for this preprocessor exists in the preset,
        # load it directly. This is required for preprocessors with nested
        # preprocessors, e.g. `StableDiffusion3TextToImagePreprocessor`.
        if check_file_exists(preset, config_file):
            try:
                preset_cls = check_preset_class(
                    preset, cls, config_file=config_file
                )
            except ValueError:
                preset_cls = None
            if preset_cls and (
                preset_cls is cls
                or issubclass(preset_cls, cls)
                or issubclass(cls, preset_cls)
            ):
                return load_from_preset(
                    preset,
                    config_file=config_file,
                    config_overrides=kwargs,
                )

        # Otherwise, reconstruct the preprocessor from its tokenizer.
        from keras_nlp.utils.preset_utils import PresetLoader

        kwargs = cls._add_missing_kwargs(
            PresetLoader(preset, config_file=TOKENIZER_CONFIG_FILE), kwargs
        )
        return cls(**kwargs)

    def __init_subclass__(cls, **kwargs):
        # Use __init_subclass__ to setup a correct docstring for from_preset.
        super().__init_subclass__(**kwargs)

        # If the subclass does not define from_preset, assign a wrapper so that
        # each class can have a distinct docstring.
        if "from_preset" not in cls.__dict__:

            def from_preset(calling_cls, *args, **kwargs):
                return super(cls, calling_cls).from_preset(*args, **kwargs)

            cls.from_preset = classmethod(from_preset)

        # Format and assign the docstring unless the subclass has overridden it.
        if cls.from_preset.__doc__ is None:
            cls.from_preset.__func__.__doc__ = Preprocessor.from_preset.__doc__
            format_docstring(
                preprocessor_name=cls.__name__,
                example_preset_name=next(iter(cls.presets), ""),
                preset_names='", "'.join(cls.presets),
            )(cls.from_preset.__func__)

