class PresetLoader:
    """Load KerasNLP layers, tokenizers, and preprocessors from a preset.

    This is a lightweight helper class used to load serialized KerasNLP
    objects from a preset directory or remote preset identifier. It supports
    loading from different config files, so that nested preprocessors and
    tokenizers can each be saved and loaded with their own config file.
    """

    def __init__(self, preset, config_file=None, config_overrides=None):
        self.preset = preset
        self.config_file = config_file or CONFIG_FILE
        self.config_overrides = config_overrides or {}

    def load_backbone(self, load_weights=True, **kwargs):
        """Load a backbone layer from the preset."""
        return load_from_preset(
            self.preset,
            load_weights=load_weights,
            config_overrides=kwargs,
        )

    def load_tokenizer(self, tokenizer_cls, config_overrides=None, **kwargs):
        """Load a tokenizer layer from the preset."""
        config_overrides = config_overrides or self.config_overrides
        return load_from_preset(
            self.preset,
            config_file=getattr(tokenizer_cls, "_config_file", "tokenizer.json"),
            config_overrides={**config_overrides, **kwargs},
        )

    def load_preprocessor(
        self, preprocessor_cls, config_file=None, **kwargs
    ):
        """Load a preprocessor layer from the preset."""
        return preprocessor_cls.from_preset(
            self.preset,
            config_file=config_file or self.config_file,
            **kwargs,
        )


def check_preset_class(
    preset,
    classes,
    config_file="config.json",
):
    """Validate a preset is being loaded on the correct class."""

